import { useRef, useMemo } from 'react';

const useFlightDataProcessor = (flightData, groupFilters = {}, segmentFilters = {}) => {
  // Sample raw response data for fallback
  const sampleRawData = useRef([
    {
      "originAirport": "LHR",
      "destinationAirport": "EWR",
      "date": "2025-03-28",
      "distance": 3459,
      "ID": "sample1",
      "source": "aeroplan",
      "YAvailable": true,
      "WAvailable": false,
      "JAvailable": true,
      "FAvailable": false,
      "YDirect": true,
      "WDirect": false,
      "JDirect": true,
      "FDirect": false,
      "YAirlines": "AC, LH, QK, UA",
      "WAirlines": "",
      "JAirlines": "UA",
      "FAirlines": "",
      "YDirectAirlines": "UA",
      "WDirectAirlines": "",
      "JDirectAirlines": "UA",
      "FDirectAirlines": "",
      "YMileageCost": "40000",
      "WMileageCost": "0",
      "JMileageCost": "80000",
      "FMileageCost": "0",
      "YTotalTaxes": 34639,
      "WTotalTaxes": 0,
      "JTotalTaxes": 55000,
      "FTotalTaxes": 0,
      "YDirectMileageCost": 40000,
      "WDirectMileageCost": 0,
      "JDirectMileageCost": 80000,
      "FDirectMileageCost": 0,
      "YDirectTotalTaxes": 35470,
      "WDirectTotalTaxes": 0,
      "JDirectTotalTaxes": 55000,
      "FDirectTotalTaxes": 0,
      "TaxesCurrency": "CAD"
    }
  ]);

  // Get enriched flight data with raw API information
  const getEnrichedFlightData = (routeCode, classCode, dateString, classData, currentFilters = {}) => {
    // Safety check for inputs
    if (!routeCode || !classCode || !dateString || !classData) {
      return [];
    }

    // Ensure flights is an array
    const flights = Array.isArray(classData[`${classCode}Flights`]) 
      ? classData[`${classCode}Flights`] 
      : [];

    // If no flights, return empty array
    if (flights.length === 0) return [];

    // Check for raw data from the flightData prop
    const rawDataArray = flightData?.rawData || sampleRawData.current || [];

    // First get flights with raw data attached
    const flightsWithRawData = flights.map(flight => {
      // If rawData is already present, just return the flight
      if (flight.rawData) return flight;

      try {
        // Find matching raw flight data
        const [origin, destination] = routeCode.split('-');

        const raw = rawDataArray.find(rawFlight => {
          return (
            (rawFlight.ID === flight.id || !flight.id) &&
            rawFlight.date === dateString &&
            rawFlight.originAirport === origin && 
            rawFlight.destinationAirport === destination &&
            rawFlight[`${classCode}Available`]
          );
        });

        // Return flight with raw data attached
        return {
          ...flight,
          rawData: raw || null
        };
      } catch (error) {
        console.warn('Error finding raw flight data:', error);
        return flight;
      }
    }).filter(flight => flight.rawData !== null);

    // If no valid flights with raw data, return empty array
    if (flightsWithRawData.length === 0) return [];

    // Now apply filters to the flights with raw data
    return applyAllFilters(flightsWithRawData, routeCode, classCode, dateString, currentFilters);
  };

  // Apply all types of filters (global, group-based, segment-based) to the flight data
  const applyAllFilters = (flights, routeCode, classCode, dateString, currentFilters) => {
    // Extract filters from parameters
    const { 
      globalFilters = {}, 
      groupFiltersForRoute = {}, 
      segmentFiltersForRoute = {}
    } = currentFilters;

    // If there are no filters, return all flights
    const hasGlobalFilters = Object.keys(globalFilters).length > 0;
    const hasGroupFilters = Object.keys(groupFiltersForRoute).length > 0;
    const hasSegmentFilters = Object.keys(segmentFiltersForRoute).length > 0;

    if (!hasGlobalFilters && !hasGroupFilters && !hasSegmentFilters) {
      return flights;
    }

    // Filter function for a single filter set
    const applyFilterSet = (flight, filterSet) => {
      const { 
        sourceFilter, 
        airlinesFilter, 
        pointsFilter, 
        dateFilter, 
        directFilter 
      } = filterSet;

      // Check source filter
      if (sourceFilter?.sources?.length > 0) {
        const isInFilter = sourceFilter.sources.includes(flight.rawData.source);
        if (sourceFilter.mode === 'include' && !isInFilter) return false;
        if (sourceFilter.mode === 'exclude' && isInFilter) return false;
      }

      // Check airlines filter
      if (airlinesFilter?.airlines?.length > 0) {
        // Get airlines for this class
        const airlinesStr = directFilter 
          ? flight.rawData[`${classCode}DirectAirlines`] 
          : flight.rawData[`${classCode}Airlines`];

        if (!airlinesStr) return false;

        const flightAirlines = airlinesStr.split(',').map(a => a.trim());
        const hasMatchingAirline = flightAirlines.some(airline => 
          airlinesFilter.airlines.includes(airline)
        );

        if (airlinesFilter.mode === 'include' && !hasMatchingAirline) return false;
        if (airlinesFilter.mode === 'exclude' && hasMatchingAirline) return false;
      }

      // Check points filter
      if (pointsFilter) {
        const mileageCost = directFilter 
          ? Number(flight.rawData[`${classCode}DirectMileageCost`] || 0) 
          : Number(flight.rawData[`${classCode}MileageCost`] || 0);

        if (mileageCost < pointsFilter[0] || mileageCost > pointsFilter[1]) return false;
      }

      // Check date filter
      if (dateFilter?.length > 0 && !dateFilter.includes(dateString)) {
        return false;
      }

      // Check direct filter
      if (directFilter && !flight.rawData[`${classCode}Direct`]) {
        return false;
      }

      return true;
    };

    // Apply filters in order: global, group, segment
    let filteredFlights = [...flights];

    // Apply global filters first
    if (hasGlobalFilters) {
      filteredFlights = filteredFlights.filter(flight => 
        applyFilterSet(flight, globalFilters)
      );
    }

    // Apply group filters next
    if (hasGroupFilters && filteredFlights.length > 0) {
      // Group filters need to match at least one filter set
      filteredFlights = filteredFlights.filter(flight => {
        // A flight passes if it matches at least one group filter
        return Object.values(groupFiltersForRoute).some(filterSet => 
          applyFilterSet(flight, filterSet)
        );
      });
    }

    // Apply segment filters last
    if (hasSegmentFilters && filteredFlights.length > 0) {
      // Similarly, segment filters need to match at least one filter set
      filteredFlights = filteredFlights.filter(flight => {
        // A flight passes if it matches at least one segment filter
        return Object.values(segmentFiltersForRoute).some(filterSet => 
          applyFilterSet(flight, filterSet)
        );
      });
    }

    return filteredFlights;
  };

  // Get unique segments from flight data
  const getUniqueSegments = () => {
    const rawData = flightData?.rawData || sampleRawData.current || [];
    const segments = new Set();

    rawData.forEach(flight => {
      const route = `${flight.originAirport}-${flight.destinationAirport}`;
      segments.add(route);
    });

    return Array.from(segments).sort();
  };

  // Get unique sources from flight data
  const getUniqueSources = () => {
    const rawData = flightData?.rawData || sampleRawData.current || [];
    const sources = new Set();

    rawData.forEach(flight => {
      if (flight.source) {
        sources.add(flight.source);
      }
    });

    return Array.from(sources).sort();
  };

  // Get unique airlines from flight data
  const getUniqueAirlines = () => {
    const rawData = flightData?.rawData || sampleRawData.current || [];
    const airlines = new Set();

    rawData.forEach(flight => {
      ['Y', 'W', 'J', 'F'].forEach(classCode => {
        const airlinesStr = flight[`${classCode}Airlines`] || '';
        if (airlinesStr) {
          airlinesStr.split(', ').forEach(airline => {
            if (airline) airlines.add(airline.trim());
          });
        }
      });
    });

    return Array.from(airlines).sort();
  };

  // Get points range for slider
  const getPointsRange = () => {
    const rawData = flightData?.rawData || sampleRawData.current || [];
    let min = Infinity;
    let max = 0;

    rawData.forEach(flight => {
      ['Y', 'W', 'J', 'F'].forEach(classCode => {
        const points = Number(flight[`${classCode}MileageCost`] || 0);
        if (points > 0) {
          min = Math.min(min, points);
          max = Math.max(max, points);
        }
      });
    });

    return [min === Infinity ? 0 : min, max];
  };

  return {
    getEnrichedFlightData,
    getUniqueSegments,
    getUniqueSources,
    getUniqueAirlines,
    getPointsRange
  };
};

export default useFlightDataProcessor;
